package com.utegear.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.OffsetDateTime; import java.time.ZoneOffset; import java.util.LinkedHashMap; import java.util.Map; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes;
@Entity @Table(name="product_variants") public class ProductVariant {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="product_id") private Product product; @Column(nullable=false,unique=true,length=50) private String sku; @JdbcTypeCode(SqlTypes.JSON) @Column(name="option_values",nullable=false,columnDefinition="jsonb") private Map<String,String> optionValues=new LinkedHashMap<>(); @Column(name="is_default",nullable=false) private boolean defaultVariant; @Column(name="price_adjustment",nullable=false,precision=12,scale=2) private BigDecimal priceAdjustment=BigDecimal.ZERO; @Column(nullable=false) private boolean active=true; @Column(name="created_at",nullable=false,updatable=false) private OffsetDateTime createdAt; @Column(name="updated_at",nullable=false) private OffsetDateTime updatedAt;
 protected ProductVariant(){} public ProductVariant(String sku,Map<String,String> options,boolean isDefault,BigDecimal adjustment){this.sku=sku;this.optionValues=options==null?new LinkedHashMap<>():new LinkedHashMap<>(options);this.defaultVariant=isDefault;this.priceAdjustment=adjustment==null?BigDecimal.ZERO:adjustment;} void attach(Product product){this.product=product;} @PrePersist void create(){createdAt=updatedAt=OffsetDateTime.now(ZoneOffset.UTC);} @PreUpdate void update(){updatedAt=OffsetDateTime.now(ZoneOffset.UTC);} public Long getId(){return id;} public String getSku(){return sku;} public Map<String,String> getOptionValues(){return optionValues;} public boolean isDefault(){return defaultVariant;} public BigDecimal getPriceAdjustment(){return priceAdjustment;} public boolean isActive(){return active;} public Product getProduct(){return product;}
}
